"use client";
// app/(app)/accountability/AccountabilityClient.js
// Accountability Centre: integrity review queue (error/warning/info findings,
// each with a concrete reason and a deep link to the record), plus upcoming
// date-driven reminders generated by the scan.

import { useState, useEffect, useMemo, useCallback } from "react";
import {
  ShieldAlert,
  ShieldCheck,
  AlertTriangle,
  AlertCircle,
  Info,
  Clock,
  ArrowRight,
  CheckCircle2,
  RefreshCw,
  ExternalLink,
  CalendarClock,
  XCircle,
} from "lucide-react";
import Button from "@/components/ui/Button";
import Badge from "@/components/ui/Badge";
import Tabs from "@/components/ui/Tabs";
import Dropdown from "@/components/ui/Dropdown";
import EmptyState from "@/components/ui/EmptyState";
import SkeletonLoader from "@/components/ui/SkeletonLoader";
import ErrorState from "@/components/ui/ErrorState";
import Link from "next/link";

const SEVERITY_CONFIG = {
  error: {
    icon: AlertTriangle,
    tone: "coral",
    label: "Error",
    border: "border-[var(--color-coral-300)]",
    bg: "bg-[var(--color-coral-50)]/20",
    iconBg: "bg-[var(--color-coral-100)] text-[var(--color-coral-700)]",
    countClass: "text-[var(--color-coral-600)]",
  },
  warning: {
    icon: AlertCircle,
    tone: "gold",
    label: "Warning",
    border: "border-[var(--color-gold-300)]",
    bg: "bg-[var(--color-gold-50)]/20",
    iconBg: "bg-[var(--color-gold-100)] text-[var(--color-gold-700)]",
    countClass: "text-[var(--color-gold-700)]",
  },
  info: {
    icon: Info,
    tone: "blue",
    label: "Info",
    border: "border-[var(--color-border)]",
    bg: "bg-[var(--color-surface)]",
    iconBg: "bg-sky-100 text-sky-700",
    countClass: "text-[var(--color-text-primary)]",
  },
};

// Legacy rows (high/medium/low) map onto the new severity scale.
function severityOf(item) {
  if (item.severity === "error" || item.severity === "high") return "error";
  if (item.severity === "warning" || item.severity === "medium") return "warning";
  return "info";
}

function daysUntil(date) {
  const DAY_MS = 24 * 60 * 60 * 1000;
  return Math.ceil((new Date(date).getTime() - Date.now()) / DAY_MS);
}

function formatDue(date) {
  const days = daysUntil(date);
  if (days < 0) return `${Math.abs(days)} day${Math.abs(days) === 1 ? "" : "s"} overdue`;
  if (days === 0) return "Due today";
  if (days === 1) return "Due tomorrow";
  return `In ${days} days`;
}

export default function AccountabilityClient({ user }) {
  const [items, setItems] = useState([]);
  const [summary, setSummary] = useState(null);
  const [reminders, setReminders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [scanning, setScanning] = useState(false);
  const [scanResult, setScanResult] = useState(null);
  const [activeTab, setActiveTab] = useState("open");
  const [selectedSeverity, setSelectedSeverity] = useState("all");
  const [error, setError] = useState(null);

  const fetchData = useCallback(async () => {
    try {
      const [itemsRes, remindersRes] = await Promise.all([
        fetch("/api/accountability?status=all"),
        fetch("/api/reminders?status=open"),
      ]);
      if (!itemsRes.ok) throw new Error("Failed to load accountability items");
      const data = await itemsRes.json();
      setItems(data.items || []);
      setSummary(data.summary || null);
      if (remindersRes.ok) {
        const rem = await remindersRes.json();
        setReminders(rem.reminders || []);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // Defer so the fetch's setState calls happen after the effect commits
    const t = setTimeout(fetchData, 0);
    return () => clearTimeout(t);
  }, [fetchData]);

  const handleRunScan = async () => {
    try {
      setScanning(true);
      setScanResult(null);
      const res = await fetch("/api/accountability", { method: "POST" });
      if (res.ok) {
        const data = await res.json();
        setScanResult(data);
        await fetchData();
      }
    } catch (err) {
      console.error("Error running integrity scan:", err);
    } finally {
      setScanning(false);
    }
  };

  const handleUpdateStatus = async (id, newStatus) => {
    try {
      const res = await fetch(`/api/accountability/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });
      if (res.ok) {
        setItems((prev) =>
          prev.map((item) => (item.id === id ? { ...item, status: newStatus } : item))
        );
      }
    } catch (err) {
      console.error("Error updating item status:", err);
    }
  };

  const handleDoneReminder = async (id) => {
    const res = await fetch(`/api/reminders/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status: "done" }),
    });
    if (res.ok) {
      setReminders((prev) => prev.filter((r) => r.id !== id));
    }
  };

  const metrics = useMemo(() => {
    const openItems = items.filter((i) => i.status === "open");
    const errors = openItems.filter((i) => severityOf(i) === "error").length;
    const warnings = openItems.filter((i) => severityOf(i) === "warning").length;
    const infos = openItems.filter((i) => severityOf(i) === "info").length;
    const resolved = items.filter((i) => i.status === "resolved").length;
    const overdueReminders = reminders.filter((r) => daysUntil(r.dueAt) < 0).length;
    return { totalOpen: openItems.length, errors, warnings, infos, resolved, overdueReminders };
  }, [items, reminders]);

  const filtered = useMemo(
    () =>
      items.filter((item) => {
        const matchesTab = item.status === activeTab;
        const matchesSev = selectedSeverity === "all" || severityOf(item) === selectedSeverity;
        return matchesTab && matchesSev;
      }),
    [items, activeTab, selectedSeverity]
  );

  return (
    <div className="p-6 md:p-8 space-y-6 max-w-screen-2xl mx-auto">
      {/* ── Header ─────────────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[var(--color-text-primary)]">
            Accountability Centre
          </h1>
          <p className="mt-1 text-sm text-[var(--color-text-secondary)]">
            Every finding names what is wrong, why it matters, and links to the record that fixes it.
          </p>
        </div>
        <Button
          variant="primary"
          icon={RefreshCw}
          loading={scanning}
          onClick={handleRunScan}
        >
          Run Integrity Scan
        </Button>
      </div>

      {scanResult && (
        <div className="p-3 rounded-[var(--radius-md)] text-xs text-[var(--color-text-secondary)] bg-[var(--color-surface-2)] border border-[var(--color-border)]">
          Scanned {Object.values(scanResult.scanned || {}).reduce((a, b) => a + b, 0)} records:
          {" "}{scanResult.findings} open finding(s), {scanResult.autoResolved} auto-resolved,{" "}
          {scanResult.remindersCreated} reminder(s) created.
        </div>
      )}

      {/* ── KPI Cards ───────────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
        <div className="p-5 rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider">
              Errors
            </span>
            <span className="p-2 rounded-full bg-[var(--color-coral-50)] text-[var(--color-coral-600)]">
              <AlertTriangle className="w-4 h-4" />
            </span>
          </div>
          <div className="mt-3 text-2xl font-bold text-[var(--color-coral-600)]">
            {metrics.errors}
          </div>
          <p className="mt-1 text-xs text-[var(--color-text-tertiary)]">
            Missing or overdue records that misstate your position
          </p>
        </div>

        <div className="p-5 rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider">
              Warnings
            </span>
            <span className="p-2 rounded-full bg-[var(--color-gold-50)] text-[var(--color-gold-700)]">
              <AlertCircle className="w-4 h-4" />
            </span>
          </div>
          <div className="mt-3 text-2xl font-bold text-[var(--color-gold-700)]">
            {metrics.warnings}
          </div>
          <p className="mt-1 text-xs text-[var(--color-text-tertiary)]">
            Stale valuations &amp; missing evidence
          </p>
        </div>

        <div className="p-5 rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider">
              Resolved
            </span>
            <span className="p-2 rounded-full bg-[var(--color-emerald-50)] text-[var(--color-emerald-600)]">
              <ShieldCheck className="w-4 h-4" />
            </span>
          </div>
          <div className="mt-3 text-2xl font-bold text-[var(--color-emerald-600)]">
            {metrics.resolved}
          </div>
          <p className="mt-1 text-xs text-[var(--color-text-tertiary)]">
            Manually fixed or auto-resolved by a re-scan
          </p>
        </div>

        <div className="p-5 rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider">
              Upcoming
            </span>
            <span className="p-2 rounded-full bg-[var(--color-surface-2)] text-[var(--color-text-primary)]">
              <CalendarClock className="w-4 h-4" />
            </span>
          </div>
          <div className="mt-3 text-2xl font-bold text-[var(--color-text-primary)]">
            {reminders.length}
            {metrics.overdueReminders > 0 && (
              <span className="ml-2 text-sm font-semibold text-[var(--color-coral-600)]">
                {metrics.overdueReminders} overdue
              </span>
            )}
          </div>
          <p className="mt-1 text-xs text-[var(--color-text-tertiary)]">
            Maturities &amp; valuation reviews on the calendar
          </p>
        </div>
      </div>

      {/* ── Tabs & Filters ──────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <Tabs
          tabs={[
            { id: "open", label: "Open Issues", count: metrics.totalOpen },
            { id: "resolved", label: "Resolved", count: metrics.resolved },
            { id: "dismissed", label: "Dismissed" },
          ]}
          activeTab={activeTab}
          onChange={setActiveTab}
        />
        <Dropdown
          value={selectedSeverity}
          onChange={setSelectedSeverity}
          options={[
            { value: "all", label: "All Severities" },
            { value: "error", label: "Errors" },
            { value: "warning", label: "Warnings" },
            { value: "info", label: "Info" },
          ]}
          size="sm"
          variant="default"
        />
      </div>

      {/* ── Findings ────────────────────────────────────────────────────── */}
      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="p-5 rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] space-y-2"
            >
              <SkeletonLoader className="h-5 w-1/3" />
              <SkeletonLoader className="h-4 w-2/3" />
            </div>
          ))}
        </div>
      ) : error ? (
        <ErrorState title="Could not load accountability items" description={error} />
      ) : filtered.length === 0 ? (
        <EmptyState
          icon={ShieldCheck}
          title={
            activeTab === "open"
              ? "No open findings"
              : `No ${activeTab} items`
          }
          description={
            activeTab === "open"
              ? "Run an integrity scan to check every record for missing, stale, or conflicting data."
              : "Items you resolve or dismiss appear here for audit history."
          }
          action={
            activeTab === "open"
              ? { label: "Run Integrity Scan", onClick: handleRunScan }
              : undefined
          }
        />
      ) : (
        <div className="space-y-3">
          {filtered.map((item) => {
            const sev = severityOf(item);
            const cfg = SEVERITY_CONFIG[sev];
            const Icon = cfg.icon;
            const isOpen = item.status === "open";
            const href = item.actionHref || "/accountability";

            return (
              <div
                key={item.id}
                className={`p-5 rounded-[var(--radius-lg)] border transition-all flex flex-col md:flex-row md:items-center justify-between gap-4 ${
                  isOpen ? `${cfg.border} ${cfg.bg}` : "border-[var(--color-border)] bg-[var(--color-surface)]"
                }`}
              >
                <div className="flex items-start gap-3.5">
                  <span className={`p-2 rounded-xl shrink-0 ${cfg.iconBg}`}>
                    <Icon className="w-5 h-5" />
                  </span>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="text-sm font-bold text-[var(--color-text-primary)]">
                        {item.title}
                      </h3>
                      <Badge tone={cfg.tone} size="sm">
                        {cfg.label}
                      </Badge>
                      {item.resolution === "auto" && (
                        <Badge tone="emerald" size="sm">
                          auto-resolved
                        </Badge>
                      )}
                    </div>
                    {item.reason && (
                      <p className="mt-1 text-xs text-[var(--color-text-secondary)] max-w-2xl">
                        {item.reason}
                      </p>
                    )}
                    <div className="mt-2 flex items-center gap-2 text-[11px] text-[var(--color-text-tertiary)]">
                      <span>Logged {new Date(item.createdAt).toLocaleDateString()}</span>
                      {item.resolvedAt && (
                        <span>
                          • Resolved {new Date(item.resolvedAt).toLocaleDateString()}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-2 shrink-0 pt-2 md:pt-0 border-t md:border-t-0 border-[var(--color-border)]">
                  {item.actionLabel && (
                    <Link href={href}>
                      <Button variant="secondary" size="sm" icon={ExternalLink}>
                        {item.actionLabel}
                      </Button>
                    </Link>
                  )}

                  {isOpen && (
                    <>
                      <Button
                        variant="primary"
                        size="sm"
                        icon={CheckCircle2}
                        onClick={() => handleUpdateStatus(item.id, "resolved")}
                      >
                        Resolve
                      </Button>
                      <button
                        type="button"
                        onClick={() => handleUpdateStatus(item.id, "dismissed")}
                        className="text-xs text-[var(--color-text-tertiary)] hover:text-[var(--color-text-primary)] p-1.5 cursor-pointer"
                        title="Dismiss finding"
                      >
                        Dismiss
                      </button>
                    </>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* ── Upcoming / Reminders ────────────────────────────────────────── */}
      <div className="rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-sm font-semibold text-[var(--color-text-primary)]">
            Upcoming &amp; Overdue
          </h2>
          <span className="text-xs text-[var(--color-text-tertiary)]">
            Generated from maturity dates and stale valuations
          </span>
        </div>
        {loading ? (
          <SkeletonLoader className="h-10 w-full" />
        ) : reminders.length === 0 ? (
          <p className="text-xs text-[var(--color-text-tertiary)]">
            No upcoming reminders. Run an integrity scan to generate them from your record dates.
          </p>
        ) : (
          <ul className="divide-y divide-[var(--color-border)]">
            {reminders.map((r) => {
              const days = daysUntil(r.dueAt);
              const overdue = days < 0;
              return (
                <li key={r.id} className="flex items-center justify-between gap-3 py-3">
                  <div className="flex items-start gap-3 min-w-0">
                    <Clock
                      size={14}
                      className={`mt-0.5 shrink-0 ${
                        overdue ? "text-[var(--color-coral-600)]" : "text-[var(--color-text-tertiary)]"
                      }`}
                    />
                    <div className="min-w-0">
                      <p className="text-xs font-medium text-[var(--color-text-primary)] truncate">
                        {r.title}
                      </p>
                      {r.body && (
                        <p className="text-[11px] text-[var(--color-text-tertiary)] truncate">
                          {r.body}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-3 shrink-0">
                    <span
                      className={`text-[11px] font-medium ${
                        overdue
                          ? "text-[var(--color-coral-600)]"
                          : "text-[var(--color-text-secondary)]"
                      }`}
                    >
                      {formatDue(r.dueAt)}
                    </span>
                    {r.entityId && (
                      <Link
                        href={
                          r.entityType === "liability"
                            ? `/assets?tab=liabilities&focus=${r.entityId}`
                            : r.entityType === "asset"
                            ? `/assets?tab=assets&focus=${r.entityId}`
                            : "/accountability"
                        }
                        className="text-[11px] text-[var(--color-emerald-600)] hover:underline"
                      >
                        View
                      </Link>
                    )}
                    <button
                      type="button"
                      onClick={() => handleDoneReminder(r.id)}
                      className="text-[11px] text-[var(--color-text-tertiary)] hover:text-[var(--color-emerald-600)] cursor-pointer"
                      title="Mark done"
                    >
                      <CheckCircle2 size={14} />
                    </button>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}
